/** ядро_ЗНАЧЕН 안의 연결형 байт_ЗНАЧЕН поток_ЗНАЧЕН. Ethernet/TCP 패킷 스택이 아닌 루프백 socket слой_ЗНАЧЕН. */
public final class поток_сеть {
    static int[] Состояние_ЗНАЧЕН = new int[16], порт_ЗНАЧЕН = new int[16], 짝 = new int[16], одноранговый_порт = new int[16], минутку_ЗНАЧЕН = new int[16], ИТ_службы_граница = new int[16];
    static int[] лицевая_камера_ЗНАЧЕН = new int[16], 수 = new int[16], данные = new int[16 * 1024];
    static int Далее_товар = 50000;
    static int проверять(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && Состояние_ЗНАЧЕН[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int номер_порта) { for (int Loop_ИНДЕКС = 0; Loop_ИНДЕКС < 16; Loop_ИНДЕКС++) if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 0 && ИТ_службы_граница[Loop_ИНДЕКС] != 0 && порт_ЗНАЧЕН[Loop_ИНДЕКС] == номер_порта) return true; return false; }
    public static int Create_ввод() {
        for (int Loop_ИНДЕКС = 0; Loop_ИНДЕКС < 16; Loop_ИНДЕКС++) if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] == 0) { Состояние_ЗНАЧЕН[Loop_ИНДЕКС] = 1; одноранговый_порт[Loop_ИНДЕКС] = порт_ЗНАЧЕН[Loop_ИНДЕКС] = лицевая_камера_ЗНАЧЕН[Loop_ИНДЕКС] = 수[Loop_ИНДЕКС] = минутку_ЗНАЧЕН[Loop_ИНДЕКС] = ИТ_службы_граница[Loop_ИНДЕКС] = 0; 짝[Loop_ИНДЕКС] = -1; return Loop_ИНДЕКС + 40; }
        return -24;
    }
    public static int BIND_участник(int 열린파일번호, int сокет_АДРЕС, int номер_порта) {
        int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9;
        if (сокет_АДРЕС != 0 && сокет_АДРЕС != 0x7f000001) return -99;
        if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 1 || номер_порта < 0 || номер_порта > 65535) return -22;
        if (номер_порта == 0) { do { номер_порта = Далее_товар++; if (Далее_товар > 65535) Далее_товар = 50000; } while (사용중(номер_порта)); }
        if (사용중(номер_порта)) return -98; порт_ЗНАЧЕН[Loop_ИНДЕКС] = номер_порта; ИТ_службы_граница[Loop_ИНДЕКС] = 1; Состояние_ЗНАЧЕН[Loop_ИНДЕКС] = 2; return 0;
    }
    public static int ожидать_передачи_данных_участник(int 열린파일번호, int невыполненная_работа) { int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9; if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 2 || невыполненная_работа < 1) return -22; Состояние_ЗНАЧЕН[Loop_ИНДЕКС] = 3; return 0; }
    public static int Подключить(int 열린파일번호, int сокет_АДРЕС, int номер_порта) {
        int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9; if (сокет_АДРЕС != 0x7f000001) return -101;
        if (номер_порта < 1 || номер_порта > 65535 || Состояние_ЗНАЧЕН[Loop_ИНДЕКС] > 2) return -22;
        int получить_страница = -1; for (int внутреннее_соединение_позиция = 0; внутреннее_соединение_позиция < 16; внутреннее_соединение_позиция++) if (Состояние_ЗНАЧЕН[внутреннее_соединение_позиция] == 3 && порт_ЗНАЧЕН[внутреннее_соединение_позиция] == номер_порта) получить_страница = внутреннее_соединение_позиция;
        if (получить_страница < 0) return -111;
        int 대기여부 = 0; for (int внутреннее_соединение_позиция = 0; внутреннее_соединение_позиция < 16; внутреннее_соединение_позиция++) if (минутку_ЗНАЧЕН[внутреннее_соединение_позиция] == получить_страница + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] == 1) { int 처리값 = BIND_участник(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int другое = Create_ввод(); if (другое < 0) return другое; другое -= 40;
        Состояние_ЗНАЧЕН[Loop_ИНДЕКС] = Состояние_ЗНАЧЕН[другое] = 4; 짝[Loop_ИНДЕКС] = другое; 짝[другое] = Loop_ИНДЕКС; порт_ЗНАЧЕН[другое] = номер_порта; одноранговый_порт[Loop_ИНДЕКС] = номер_порта; одноранговый_порт[другое] = порт_ЗНАЧЕН[Loop_ИНДЕКС]; минутку_ЗНАЧЕН[другое] = получить_страница + 1; return 0;
    }
    public static int принять_контакт(int 열린파일번호) { int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9; if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 3) return -22; for (int внутреннее_соединение_позиция = 0; внутреннее_соединение_позиция < 16; внутреннее_соединение_позиция++) if (Состояние_ЗНАЧЕН[внутреннее_соединение_позиция] != 0 && минутку_ЗНАЧЕН[внутреннее_соединение_позиция] == Loop_ИНДЕКС + 1) { минутку_ЗНАЧЕН[внутреннее_соединение_позиция] = 0; return внутреннее_соединение_позиция + 40; } return -11; }
    public static int Запись(int 열린파일번호, int ввод_СЧЁТ) {
        int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9; if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 4) return -107;
        if (ввод_СЧЁТ < 0 || ввод_СЧЁТ > 512) return -22; if (ввод_СЧЁТ == 0) return 0;
        int внутреннее_соединение_позиция = 짝[Loop_ИНДЕКС]; if (внутреннее_соединение_позиция < 0) return -32; int итог_СЧЁТ = 1024 - 수[внутреннее_соединение_позиция]; if (итог_СЧЁТ == 0) return -11; if (итог_СЧЁТ > ввод_СЧЁТ) итог_СЧЁТ = ввод_СЧЁТ;
        for (int Сравнение_позиция = 0; Сравнение_позиция < итог_СЧЁТ; Сравнение_позиция++) данные[внутреннее_соединение_позиция * 1024 + (лицевая_камера_ЗНАЧЕН[внутреннее_соединение_позиция] + 수[внутреннее_соединение_позиция] + Сравнение_позиция) % 1024] = замыкание_на_себя_сеть.вперед_ЗНАЧЕН[Сравнение_позиция]; 수[внутреннее_соединение_позиция] += итог_СЧЁТ; return итог_СЧЁТ;
    }
    public static int Чтение(int 열린파일번호, int ввод_СЧЁТ) {
        int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9; if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] != 4) return -107; if (ввод_СЧЁТ < 0 || ввод_СЧЁТ > 512) return -22;
        if (ввод_СЧЁТ == 0) return 0; if (수[Loop_ИНДЕКС] == 0) return 짝[Loop_ИНДЕКС] < 0 ? 0 : -11; if (ввод_СЧЁТ > 수[Loop_ИНДЕКС]) ввод_СЧЁТ = 수[Loop_ИНДЕКС];
        for (int Сравнение_позиция = 0; Сравнение_позиция < ввод_СЧЁТ; Сравнение_позиция++) замыкание_на_себя_сеть.вперед_ЗНАЧЕН[Сравнение_позиция] = данные[Loop_ИНДЕКС * 1024 + (лицевая_камера_ЗНАЧЕН[Loop_ИНДЕКС] + Сравнение_позиция) % 1024]; лицевая_камера_ЗНАЧЕН[Loop_ИНДЕКС] = (лицевая_камера_ЗНАЧЕН[Loop_ИНДЕКС] + ввод_СЧЁТ) % 1024; 수[Loop_ИНДЕКС] -= ввод_СЧЁТ; return ввод_СЧЁТ;
    }
    public static int чтение_участник_порт(int 열린파일번호) { int Loop_ИНДЕКС = проверять(열린파일번호); return Loop_ИНДЕКС < 0 ? -9 : порт_ЗНАЧЕН[Loop_ИНДЕКС]; }
    public static int чтение_одноранговый_порт(int 열린파일번호) { int Loop_ИНДЕКС = проверять(열린파일번호); return Loop_ИНДЕКС < 0 ? -9 : одноранговый_порт[Loop_ИНДЕКС]; }
    public static int Закрыть(int 열린파일번호) {
        int Loop_ИНДЕКС = проверять(열린파일번호); if (Loop_ИНДЕКС < 0) return -9;
        if (Состояние_ЗНАЧЕН[Loop_ИНДЕКС] == 3) for (int внутреннее_соединение_позиция = 0; внутреннее_соединение_позиция < 16; внутреннее_соединение_позиция++) if (минутку_ЗНАЧЕН[внутреннее_соединение_позиция] == Loop_ИНДЕКС + 1) { if (짝[внутреннее_соединение_позиция] >= 0) 짝[짝[внутреннее_соединение_позиция]] = -1; Состояние_ЗНАЧЕН[внутреннее_соединение_позиция] = минутку_ЗНАЧЕН[внутреннее_соединение_позиция] = ИТ_службы_граница[внутреннее_соединение_позиция] = 0; }
        if (짝[Loop_ИНДЕКС] >= 0) 짝[짝[Loop_ИНДЕКС]] = -1; Состояние_ЗНАЧЕН[Loop_ИНДЕКС] = ИТ_службы_граница[Loop_ИНДЕКС] = 수[Loop_ИНДЕКС] = минутку_ЗНАЧЕН[Loop_ИНДЕКС] = 0; return 0;
    }
}
